#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn count_matches_ace_enum() {
        // ACE.Entity.Enum.SpellCategory ships 730 named entries
        // (0..733 with gaps at 622, 700..703). If this count changes,
        // re-run the extractor.
        assert_eq!(count(), 729);
    }

    #[test]
    fn sorted_for_binary_search() {
        for window in SPELL_CATEGORY_NAMES.windows(2) {
            assert!(
                window[0].0 < window[1].0,
                "table not sorted: ({}, {:?}) >= ({}, {:?})",
                window[0].0, window[0].1, window[1].0, window[1].1
            );
        }
    }

    #[test]
    fn name_lookup_known_values() {
        assert_eq!(name(0), Some("Undef"));
        assert_eq!(name(1), Some("StrengthRaising"));
        assert_eq!(name(2), Some("StrengthLowering"));
        // Mid-table — verify binary search reaches deep entries.
        assert_eq!(name(250), Some("Dispel"));
        assert_eq!(name(500), Some("RunRaisingRare"));
        // High end.
        assert_eq!(name(733), Some("GauntletCriticalDamageReductionRatingRaising"));
    }

    #[test]
    fn name_lookup_gaps_return_none() {
        // ACE.Entity.Enum.SpellCategory has gaps at 622 and 700..703.
        assert_eq!(name(622), None);
        assert_eq!(name(700), None);
        assert_eq!(name(701), None);
        assert_eq!(name(702), None);
        assert_eq!(name(703), None);
        // Past the high end.
        assert_eq!(name(734), None);
        assert_eq!(name(99_999), None);
    }
}
